from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext


def _number(value):
    if not isinstance(value, str):
        raise ValueError('必须为十进制字符串')
    try:
        number = Decimal(value)
    except InvalidOperation as exc:
        raise ValueError('金额无效') from exc
    if not number.is_finite() or number < 0:
        raise ValueError('金额无效')
    return number


def price_order(items, discounts=()):
    with localcontext() as context:
        context.prec = 120
        total = Decimal(0)
        for row in items:
            try:
                amount, qty = _number(row['price']), row['qty']
            except (KeyError, TypeError) as exc:
                raise ValueError('订单字段无效') from exc
            if type(qty) is not int or qty < 0:
                raise ValueError('数量无效')
            total += amount * qty
        for value in discounts:
            discount = _number(value)
            if discount > 1:
                raise ValueError('折扣无效')
            total *= 1 - discount
        return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

