    assert stock == {'a': 1}
    assert solution.reserve(stock, 'a', 1, lock) is True


@_case
def check_interleaving():
    first_read, release, second_done = threading.Event(), threading.Event(), threading.Event()
    writes, read_holds = [], []
    class Stock(dict):
        def __getitem__(self, key):
            value = super().__getitem__(key)
            if threading.current_thread().name == '甲' and not first_read.is_set():
                read_holds.append(lock._is_owned())
                first_read.set()
                assert release.wait(4), '控制器未释放'
            return value
        def get(self, key, default=None):
            return self[key] if key in self else default
        def __setitem__(self, key, value):
            writes.append((threading.current_thread().name, key, lock._is_owned()))
            return super().__setitem__(key, value)
    stock, lock, results, errors = Stock(a=1, b=9), threading.RLock(), {}, []
    def worker():
        try:
            results[threading.current_thread().name] = solution.reserve(stock, 'a', 1, lock)
        except BaseException as exc:
            errors.append(repr(exc))
        finally:
            if threading.current_thread().name == '乙':
                second_done.set()
    first = threading.Thread(target=worker, name='甲', daemon=True)
    second = threading.Thread(target=worker, name='乙', daemon=True)
    first.start()
    try:
        assert first_read.wait(2), '未通过下标或 get 读取库存'
        held_at_read = read_holds[0]
        second.start()
        # 未持锁时强制乙先提交；已持锁时释放甲以免要求锁内交错。
        if not held_at_read:
            assert second_done.wait(2), '未持共享锁却阻塞竞争调用'
    finally:
        release.set()
        first.join(3)
        if second.ident is not None:
            second.join(3)
    assert not first.is_alive() and not second.is_alive(), '死锁'
    assert held_at_read, '首次读取未持共享锁，事后重读不能替代临界区'
    assert not errors, errors
    assert all(type(value) is bool for value in results.values())
    assert sorted(results.values()) == [False, True], results
    assert dict(stock) == {'a': 0, 'b': 9}, stock
    assert writes and all(results[name] is True and key == 'a' and owned for name, key, owned in writes), '只允许成功调用在拥有共享锁时写入'


