def find_customer(customers, customer_id, *, include_inactive=False, fields=None):
    if type(customer_id) is not int or customer_id <= 0:
        raise ValueError('客户编号无效')
    if type(include_inactive) is not bool:
        raise ValueError('查询选项无效')
    if fields is not None:
        allowed = {'id', 'name', 'email', 'active', 'metadata'}
        if not isinstance(fields, tuple) or any(not isinstance(key, str) or key not in allowed for key in fields) or len(set(fields)) != len(fields):
            raise ValueError('字段无效')
    for customer in customers:
        if customer['id'] == customer_id and (include_inactive or customer['active']):
            if fields is None:
                return deepcopy(customer)
            return deepcopy({key: customer.get(key) for key in fields})
    return None

