import re
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext


def clean_rows(rows):
    records, errors, seen = [], [], set()
    for index, row in enumerate(rows):
        field = 'row'
        try:
            if not isinstance(row, dict):
                raise ValueError()
            field = 'id'
            key = row.get('id')
            if not isinstance(key, str) or not key.strip():
                raise ValueError()
            key = key.strip()
            field = 'amount'
            value = row.get('amount')
            if not isinstance(value, str):
                raise ValueError()
            with localcontext() as context:
                context.prec = 50
                amount = Decimal(value)
                if not amount.is_finite() or amount < 0:
                    raise ValueError()
                cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
            field = 'date'
            day = row.get('date')
            if not isinstance(day, str) or re.fullmatch(r'[0-9]{4}-[0-9]{2}-[0-9]{2}', day) is None:
                raise ValueError()
            date.fromisoformat(day)
            field = 'email'
            email = row.get('email')
            if email is not None:
                if not isinstance(email, str):
                    raise ValueError()
                email = email.strip().lower() or None
                if email is not None and re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+', email) is None:
                    raise ValueError()
        except (ValueError, InvalidOperation):
            errors.append({'index':index,'field':field})
            continue
        if key not in seen:
            seen.add(key)
            records.append({'id':key,'amount_cents':cents,'date':day,'email':email})
    return {'records':records,'errors':errors}

